#!/usr/bin/env node
// Generates every port artefact from packages/config/ports.json.
//   node tools/gen-ports.mjs          write the files
//   node tools/gen-ports.mjs --check  fail (exit 1) if any generated file is stale (used in CI)
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const spec = JSON.parse(readFileSync(join(root, "packages/config/ports.json"), "utf8"));
const check = process.argv.includes("--check");

// ---- validation: unique, inside its block, inside the series -------------
const seen = new Map();
for (const s of spec.services) {
  const block = spec.blocks[s.block];
  if (!block) throw new Error(`${s.key}: unknown block "${s.block}"`);
  if (s.port < block.from || s.port > block.to) throw new Error(`${s.key}: ${s.port} is outside block ${s.block} (${block.from}-${block.to})`);
  if (seen.has(s.port)) throw new Error(`Port ${s.port} used by both ${seen.get(s.port)} and ${s.key}`);
  seen.set(s.port, s.key);
}

const header = "GENERATED by tools/gen-ports.mjs from packages/config/ports.json. Do not edit.";
const staging = (p) => p + spec.stagingOffset;

const env = [
  `# ${header}`,
  "# Production / local ports",
  ...spec.services.map((s) => `${s.key}_PORT=${s.port}`),
  "",
  `# Staging ports (production + ${spec.stagingOffset})`,
  ...spec.services.map((s) => `STAGING_${s.key}_PORT=${staging(s.port)}`),
  "",
].join("\n");

const ts = [
  `// ${header}`,
  "export const PORTS = {",
  ...spec.services.map((s) => `  ${s.key}: ${s.port},`),
  "} as const;",
  "",
  `export const STAGING_PORT_OFFSET = ${spec.stagingOffset};`,
  "",
  "export type PortKey = keyof typeof PORTS;",
  "",
].join("\n");

const md = [
  "# Port map",
  "",
  `> ${header}`,
  "",
  "Every HeyMey service on the single VPS uses a port from one series that starts at **4567**.",
  "Only Caddy listens on the public internet (80/443); every port below binds to `127.0.0.1` in production.",
  `Staging runs the same services at **production port + ${spec.stagingOffset}**.`,
  "",
  "| Block | Range | Purpose |",
  "|---|---|---|",
  ...Object.entries(spec.blocks).map(([k, b]) => `| ${k} | ${b.from}–${b.to} | ${b.note} |`),
  "",
  "| Port | Staging | Service | Env var | Public host | What |",
  "|---|---|---|---|---|---|",
  ...spec.services.map(
    (s) => `| **${s.port}** | ${staging(s.port)} | \`${s.service}\` | \`${s.key}_PORT\` | ${s.host ? `\`${s.host}\`` : "—"} | ${s.description} |`,
  ),
  "",
  "Unlisted ports inside a block are reserved for that block. To add a service: edit `packages/config/ports.json`, run `pnpm ports:gen`, commit all generated files.",
  "",
].join("\n");

const outputs = {
  "infra/compose/ports.env": env,
  "packages/config/src/ports.generated.ts": ts,
  "docs/architecture/ports.md": md,
};

let stale = [];
for (const [rel, content] of Object.entries(outputs)) {
  const file = join(root, rel);
  const current = existsSync(file) ? readFileSync(file, "utf8").replace(/\r\n/g, "\n") : null;
  if (current === content) continue;
  if (check) stale.push(rel);
  else {
    writeFileSync(file, content);
    console.log(`wrote ${rel}`);
  }
}
if (check && stale.length) {
  console.error(`Port files are stale. Run \`pnpm ports:gen\`:\n  ${stale.join("\n  ")}`);
  process.exit(1);
}
if (check) console.log("ports: up to date");
